INSERT INTO `characters` (`id`, `char_slug`, `name_jp`, `name_en`, `battle_type`, `range_type`, `difficulty`, `vitality`, `profile_text`, `season`, `announce_date`, `announce_event`, `release_date`, `release_season`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'ryu', 'リュウ', 'RYU', 'スタンダード', 'ミドルレンジ', 'ノーマル', 10000, '真の強さを求め修行を続ける格闘家。  \\n礼儀正しく誠実な性格で、自分より強い相手と闘うために世界を旅する。「殺意の波動」との相克を超え、更なる高みへと探求に向かう。', 0, NULL, NULL, NULL, NULL, 1100, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(2, 'luke', 'ルーク', 'LUKE', 'スタンダード', 'ミドルレンジ', 'ノーマル', 10000, '民間警備会社のコントラクター。米軍特殊部隊上がりで、初心者に総合格闘技を指導している。  \\n余暇に楽しむのはスナック菓子とゲーム、格闘。  \\n勝負事となると勝ちは決して譲らない。', 0, NULL, NULL, NULL, NULL, 100, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(3, 'jamie', 'ジェイミー', 'JAMIE', 'トリッキー', 'ミドルレンジ', 'ノーマル', 10000, '自称・中華街のトラブルバスター。  \\n憧れる「双龍」ユン・ヤン兄弟にならい、道理や仲間を尊ぶ義と、拳法の武によって街を守っている。特技はダンス全般。', 0, NULL, NULL, NULL, NULL, 200, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(4, 'chunli', '春麗', 'CHUN-LI', 'スピード', 'ミドルレンジ', 'ハード', 10000, '華麗な脚技で闘う元・ICPOの捜査官。  \\n黒い月事件の被害者だったリーフェンの保護者。  \\n宿願だったシャドルー壊滅を果たし、現在はカンフー教室を開いて街の人々と親しんでいる。', 0, NULL, NULL, NULL, NULL, 1600, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(5, 'guile', 'ガイル', 'GUILE', 'スタンダード', 'ロングレンジ', 'ノーマル', 10000, '祖国の平和のために闘う米空軍軍人。  \\nシャドルーを壊滅させ、親友・ナッシュの復讐を果たした。妻子との平穏な日常を喜びながらもその眼は新たな戦場を見据えている。', 0, NULL, NULL, NULL, NULL, 1400, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(6, 'kimberly', 'キンバリー', 'KIMBERLY', 'スピード', 'ミドルレンジ', 'ノーマル', 10000, '武神流第39代目伝承者・ガイの押し掛け弟子。  \\nごく普通の家庭に生まれ、学生時代は超優等生。  \\n飛び級で大学を卒業後、故あってニンジャを志した。80年代のポップカルチャーが大好き。', 0, NULL, NULL, NULL, NULL, 400, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(7, 'juri', 'ジュリ', 'JURI', 'スピード', 'ショートレンジ', 'ハード', 10000, '人の争いや苦悩を好み、闘う相手を破壊し尽くすことを至高の喜びとする享楽家。  \\n左目を奪ったベガへの恨みという動機を失った現在、鬱屈した日々を過ごしている。', 0, NULL, NULL, NULL, NULL, 800, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(8, 'ken', 'ケン', 'KEN', 'パワー', 'ミドルレンジ', 'ノーマル', 10000, '元・全米格闘王、元・マスターズ財団副理事長。  \\nある事件により組織犯罪の首謀者という嫌疑をかけられたため、家族の元を離れ地位を捨てて潜伏している。', 0, NULL, NULL, NULL, NULL, 1500, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(9, 'blanka', 'ブランカ', 'BLANKA', 'スピード', 'ミドルレンジ', 'ノーマル', 10000, '心やさしい大自然の戦士。  \\nジャングルを知り尽くした自信と、いつか人気者になる夢を胸に、アドベンチャーツアーのガイドをして母との暮らしを支えている。', 0, NULL, NULL, NULL, NULL, 1300, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(10, 'dhalsim', 'ダルシム', 'DHALSIM', 'トリッキー', 'ロングレンジ', 'ハード', 10000, 'インドの修行僧でヨーガの達人。人々の導き手となり、無数の悩みや苦しみの声に応えている。  \\n無益な争いは好まないが、悪事を許せない性格ゆえに、闘いの場では厳しさも見せる。', 0, NULL, NULL, NULL, NULL, 1800, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(11, 'ehonda', 'E・本田', 'E.HONDA', 'パワー', 'ミドルレンジ', 'ノーマル', 10500, '相撲を「わあるどわいど」にするため闘う力士。  \\n実力は横綱級だが、本場所そっちのけで世界を飛び回る破天荒さゆえ、番付は張出大関である。  \\n料理は玄人裸足の腕前で、ちゃんこ鍋が絶品。', 0, NULL, NULL, NULL, NULL, 1200, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(12, 'deejay', 'DJ', 'DEE JAY', 'トリッキー', 'ミドルレンジ', 'ノーマル', 10000, 'ダンスミュージックの世界的大スター。  \\nいつも陽気でノリが軽い。音楽と格闘への熱い愛をたぎらせ、刺激的な新曲や、観客を沸かせるパフォーマンスを構想している。', 0, NULL, NULL, NULL, NULL, 900, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(13, 'manon', 'マノン', 'MANON', 'パワー', 'ミドルレンジ', 'ノーマル', 10000, '世界大会優勝経験を持つ柔道家にして、スーパーモデル。常に高い理想を抱き、自身を磨き続ける美の探求者。世界最強のモデルとなるべくストリートファイトのステージに上がる。', 0, NULL, NULL, NULL, NULL, 300, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(14, 'marisa', 'マリーザ', 'MARISA', 'パワー', 'ミドルレンジ', 'イージー', 10500, '古代ギリシャからの歴史を継ぐ闘士にして新進のジュエリーデザイナー。幼い頃に全盛期のコロッセオを幻視した体験がある。豪放磊落な笑顔と、繊細な審美眼をあわせ持つ。', 0, NULL, NULL, NULL, NULL, 500, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(15, 'jp', 'JP', 'JP', 'トリッキー', 'ロングレンジ', 'ハード', 10000, '国際NGOを組織し多数の開発投資プロジェクトを成功させてきた事業家。小国ナイシャールに現在の繁栄をもたらした。愛猫の名はシベール。', 0, NULL, NULL, NULL, NULL, 700, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(16, 'zangief', 'ザンギエフ', 'ZANGIEF', 'パワー', 'ショートレンジ', 'ハード', 11000, '「赤きサイクロン」の異名を持つ巨漢のプロレスラー。  \\n筋肉こそ至高という独自の理論を提唱し、肉体進化と後進の指導に励んでいる。', 0, NULL, NULL, NULL, NULL, 1700, '2026-03-08 11:56:39', '2026-03-08 11:56:39'),
(17, 'lily', 'リリー', 'LILY', 'スタンダード', 'ミドルレンジ', 'イージー', 10000, 'サンダーフット族の古い血を受け継ぐ娘。  \\n自然界に宿る精霊と語らう力を持ち、精霊の導きによって世界を巡る旅に出る。天真爛漫な姿からは想像もつかない巨大な力を秘める。', 0, NULL, NULL, NULL, NULL, 600, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(18, 'cammy', 'キャミィ', 'CAMMY', 'スピード', 'ショートレンジ', 'ノーマル', 10000, 'イギリス特殊部隊デルタレッド隊員。  \\n自身と深い因縁のあるシャドルーに対する作戦で戦功を挙げた。非常に優秀だが、気まぐれな一面を見せることも。現在は本部勤めで鋭気を養う。', 0, NULL, NULL, NULL, NULL, 1000, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(19, 'rashid', 'ラシード', 'RASHID', 'トリッキー', 'ミドルレンジ', 'ハード', 10000, 'パルクールの身ごなしで空駆ける、砂漠の荒鷲。風を味方に、高い機動力で相手を翻弄。古い王家の血をひく高貴な生まれで、言動は軽いけれど根は誠実。趣味は動画配信。', 1, '2023-04-21', 'ストリートファイター6 ショーケース', '2023-07-24', '2023年夏', 1900, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(20, 'aki', 'A.K.I', 'A.K.I', 'トリッキー', 'ロングレンジ', 'ハード', 10000, '元シャドルー幹部、F.A.N.Gに師事する毒遣い。  \\n毒に魅せられ、その力をふるうことに無上の歓びを覚える。  \\nF.A.N.Gを先生と呼び偏愛している。', 1, '2023-04-21', 'ストリートファイター6 ショーケース', '2023-09-27', '2023年秋', 2000, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(21, 'ed', 'エド', 'ED', 'トリッキー', 'ロングレンジ', 'ハード', 10000, 'サイコパワーを操る青年。  \\nシャドルーの実験により、少年から急激に成長。  \\n他の実験体を解放しようと旅をしている。  \\n気の短さと口の悪さはバイソン仕込み。', 1, '2023-04-21', 'ストリートファイター6 ショーケース', '2024-02-27', '2024年冬', 2100, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(22, 'gouki', '豪鬼', 'AKUMA', 'スタンダード', 'ミドルレンジ', 'ノーマル', 9000, '己が拳を極めんため、殺意の波動を身に宿し闘い続ける修羅。', 1, '2023-04-21', 'ストリートファイター6 ショーケース', '2024-05-22', '2024年春', 2200, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(23, 'vega', 'ベガ', 'M.BISON', 'パワー', 'ミドルレンジ', 'ハード', 10000, '死んだはずのシャドルー総帥、ベガらしき男。  \\n記憶の一部を失っているが、その性は暴虐にして不遜。  \\nサイコパワーに導かれ、シャドルー関連施設に現れる。', 2, '2024-06-07', 'Summer Game Fest 2024', '2024-06-26', '2024年夏', 2300, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(24, 'terry', 'テリー', 'TERRY', 'スタンダード', 'ミドルレンジ', 'ノーマル', 10000, '腕を磨くために世界をさすらい、闘い続ける熱いファイター。飢えた狼の異名をとる。パオパオカフェの支店がオープンすると聞きつけて、メトロシティに立ち寄った。', 2, '2024-06-07', 'Summer Game Fest 2024', '2024-09-24', '2024年秋', 2400, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(25, 'mai', '舞', 'MAI', 'スタンダード', 'ミドルレンジ', 'ノーマル', 10000, '不知火流忍術継承者。恋に修行にひたむきな魅惑のくノ一。料理に和裁、華道や日本舞踊など、忍びの技以外も多才。', 2, '2024-06-07', 'Summer Game Fest 2024', '2025-02-05', '2025年冬', 2500, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(26, 'elena', 'エレナ', 'ELENA', 'トリッキー', 'ミドルレンジ', 'ハード', 10000, 'サバンナの誇り高き戦士の一族。  \\n大地と風に育まれた明朗活発天然娘。  \\n癒やし手の資質を持ち、目指すは動物のお医者さん。', 2, '2024-06-07', 'Summer Game Fest 2024', '2025-06-04', '2025年春', 2600, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(27, 'sagat', 'サガット', 'SAGAT', 'パワー', 'ロングレンジ', 'イージー', 10000, 'ムエタイ界の帝王。後に巨大犯罪組織シャドルーの幹部となるが、現在は離脱。いち武道家として、深山にて修行を続けている。', 3, '2024-06-08', 'Summer Game Fest 2025', '2025-08-05', '2025年夏', 2700, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(28, 'cviper', 'ヴァイパー', 'C.VIPER', 'トリッキー', 'ミドルレンジ', 'ハード', 10000, '某諜報機関所属の潜入工作員。  \\nクールでタフなリアリスト。  \\nスーツに仕込んだギミックで格闘能力を高めている。', 3, '2024-06-08', 'Summer Game Fest 2025', '2025-10-05', '2025年秋', 2800, '2026-03-08 11:56:40', '2026-03-08 11:56:40'),
(29, 'alex', 'アレックス', 'ALEX', 'パワー', 'ミドルレンジ', 'ハード', 10500, '次代を担うと評される若き格闘家。育ての親トムをトレーナーにリングデビューしたが、あまりの無愛想さゆえヒール扱い。', 3, '2025-06-07', 'Summer Game Fest 2025', NULL, '2026年春の前半', 2900, '2026-03-18 15:25:51', '2026-03-18 15:25:51');
