(6, 1, 'corner-normal-2', 'jump', 'general', 'ジャンプ攻撃始動', 'j.HP -> 4HP -> 236HK -> 623LP', 'Beginner', 'Corner', 'Normal', 'Ground', 'None', NULL, 'j.HP', '623LP', 3410, 0, 0, 0, '画面端の場合は弱昇竜拳までつながる。', 600, '2026-03-14 13:35:56', '2026-03-19 14:28:59'),
(7, 1, 'mid-normal-4', 'crossup', 'general', 'めくりジャンプ攻撃始動', 'j.MK -> MP -> 4HP -> 236HK', 'Advanced', 'Mid', 'Normal', 'Ground', 'None', NULL, 'j.MK', '236HK', 2440, 0, 0, 0, 'ジャンプ中キックをめくりでヒットさせると距離が近くなるので中パンチから引強パンチがつながるようになる。', 700, '2026-03-14 13:35:56', '2026-03-19 14:28:59'),
