(9, 1, 'mid-normal-5', 'rush', 'general', 'ラッシュ', '[NR] -> HP -> 4HP -> 236HK', 'Beginner', 'Mid', 'Normal', 'Ground', 'None', NULL, '[NR]', '236HK', 2640, 1, 0, 0, 'ラッシュから強Pを使用することで引強Pがつながり汎用コンボを使用できる。', 900, '2026-03-14 13:35:56', '2026-03-19 14:28:59'),
(10, 1, 'corner-normal-4', 'rush', 'general', 'ラッシュ', '[NR] -> HP -> 4HP -> 236HK -> 623LP', 'Beginner', 'Corner', 'Normal', 'Ground', 'None', NULL, '[NR]', '623LP', 3410, 1, 0, 0, '画面端の場合は弱昇竜拳までつながる。', 1000, '2026-03-14 13:35:56', '2026-03-19 14:28:59'),
(11, 1, 'any-punish-1', 'impact', 'general', 'インパクト(パニカン)', '[IM] -> 6HP -> 2MP -> 623HP', 'Beginner', 'Any', 'Punish', 'Ground', 'None', NULL, '[IM]', '623HP', 2620, 1, 0, 0, 'インパクトがパニカンしたら汎用コンボを使用してもいいがこのコンボを使用することで火力が上がる。', 1100, '2026-03-14 13:35:57', '2026-03-19 14:28:59'),
(12, 1, 'corner-normal-wallsplat-1', 'impact', 'general', '壁やられ', '[IM] -> 4HP -> 214MP -> 623HP', 'Intermediate', 'Corner', 'Normal', 'Ground', 'WallSplat', NULL, '[IM]', '623HP', 2840, 1, 0, 0, '汎用コンボを使用してもよいがこのコンボは火力が伸びる。', 1200, '2026-03-14 13:35:57', '2026-03-19 14:28:59'),
(13, 1, 'corner-normal-stun-1', 'impact', 'general', 'スタン', '[IM] -> 22P -> j.HP -> 2HP -> 214HP -> 623HP', 'Intermediate', 'Corner', 'Normal', 'Ground', 'Stun', NULL, '[IM]', '623HP', 3220, 1, 0, 0, '電刃錬気を溜める事で引強パンチから強波掌撃がつながりさらに強昇龍拳までコンボすることができる。', 1300, '2026-03-14 13:35:57', '2026-03-19 14:28:59'),
(14, 1, 'any-punish-2', 'punish', 'general', '無敵技ガード後', 'HK -> 4HP -> 623HP', 'Beginner', 'Any', 'Punish', 'Ground', 'None', NULL, 'HK', '623HP', 3000, 0, 0, 0, 'ダメージの高い強昇竜拳を使用している。', 1400, '2026-03-14 13:35:57', '2026-03-19 14:28:59'),
(15, 2, 'mid-normal-1', 'general', 'general', '汎用コンボ 中央', '2HP -> 214MP[J] -> 214LP[J] -> 214HP[J]', 'Intermediate', 'Mid', 'Normal', 'Ground', 'None', NULL, '2HP', '214HP', 3200, 0, 0, 1, 'このコンボは全てジャストにする必要がある。', 100, '2026-03-14 13:36:23', '2026-03-19 14:28:59'),
(16, 2, 'mid-normal-2', 'general', 'general', '汎用コンボ 中央 ジャストミス', '2HP -> 214MP[J/H] -> 214LP[H] -> 214MP', 'Intermediate', 'Mid', 'Normal', 'Ground', 'None', NULL, '2HP', '214HP', 3200, 0, 0, 0, '中フラッシュナックルのジャストをミスった時用のコンボ。', 200, '2026-03-14 13:36:23', '2026-03-19 14:28:59'),
(17, 2, 'corner-normal-1', 'general', 'general', '汎用コンボ 画面端', '2HP -> 214LP[J] -> 214HP[J]', 'Intermediate', 'Corner', 'Normal', 'Ground', 'None', NULL, '2HP', '214HP', 2360, 0, 0, 1, '画面端付近で使用するコンボ。ダメージは落ちてしまう。', 300, '2026-03-14 13:36:23', '2026-03-19 14:28:59'),
