INSERT INTO `combos_backup` (`slug`, `char_slug`, `type`, `group_key`, `category_label`, `moves`, `damage`, `continuation`, `text`, `sort_order`) VALUES
('jamie_fourF_level0', 'jamie', 'fourF', 'level0', '酔いレベル0時', '2.LP;shoryu.HP', '', '', '鋭鍾打(弱P>弱K>中P)という特殊技はLv1から使うことができるので0の時は強張弓腿を使い魔身をしてレベルを上げましょう。', 203),
('jamie_fourF_level1', 'jamie', 'fourF', 'level1', '酔いレベル1以上', '2.LP;[LP;LK;MP];[hadou.P;6.P;6.P];or;[hadou.P;6.K;6.K]', '', '', '流酔拳はダメージやSA3に派生させるとき、流酔脚は酔いレベルを上げるときに使う。', 204),
('jamie_general_level1', 'jamie', 'general', 'level1', '酔いレベル1以下', '2.HP;shoryu.HP;22.P', '', '', 'レベル1以下の時は強張弓腿を使い魔身をしてレベルを上げましょう。', 201),
('jamie_general_level2', 'jamie', 'general', 'level2', '酔いレベル2以上', '2.HP;hadou.K', '', '', '爆廻は酔いレベルが2以上から使えることができる技なのでレベル2以上になったタイミングで強張弓腿の部分を爆廻にする', 202),
('jamie_impact_punish', 'jamie', 'impact', 'punish', 'パニッシュカウンター', '2.HP;shoryu.HP;22.P', '', '', 'インパクトがパニカンしたら汎用コンボを使用。', 208),
('jamie_impact_stan', 'jamie', 'impact', 'stan', 'スタン', '22.P(ホールド);2.HP;shoryu.HP', '', '', '魔身を長押し(ホールド)すると素早く2杯飲むことができる。', 210),
('jamie_impact_wall', 'jamie', 'impact', 'wall', '壁やられ', '2.HP;shoryu.LP', '', '', '弱張弓腿から前ジャンプで安全飛びができる。<br>安全飛びについてはこちらの<a href=\\\"./Term.html\\\">用語</a>から', 209),
('jamie_jump_cross_up', 'jamie', 'jump', 'cross_up', 'めくりヒット', 'J.MK;2.LP;shoryu.HP', '', '', 'J中Kを当てたとき弱Pを二回うち当たっているか確認してから4F始動同様のコンボを使用。', 206),
('jamie_jump_normal', 'jamie', 'jump', 'normal', '通常ヒット', 'J.HP;2.HP;shoryu.HP;or;hadou.K', '', '', 'J強Pからは汎用コンボを使用。レベル2以上の場合は爆廻を使用', 205),
('jamie_rush', 'jamie', 'rush', '', '', 'Nrush;2.MP;2.HP;shoryu.HP', '', '', 'ラッシュ攻撃には、有利フレームを増やす性質があるので屈中Pから屈強Pを打ち汎用コンボを使用。', 207),
('jamie_shimmy', 'jamie', 'shimmy', '', '', 'HK;2.HP;shoryu.HP', '', '', '強Kがパニッシュカウンターすると特殊やられになり屈強が入るようになり汎用コンボを使用することができる。', 211),
('luke_fourF', 'luke', 'fourF', '', '', '2.LP;tatsu.LP', '', '', '弱フラッシュナックルはガードされると確定反撃があるのでガードされたら弱サンブラストを使用。', 1002),
('luke_general', 'luke', 'general', '', '', '2.HP;tatsu.MP(ジャスト);tatsu.LP(ジャスト);tatsu.HP(ジャスト)', '', '', '強フラッシュナックルからは、SA3をキャンセルで使うことができる。<br>このコンボは全てジャストにする必要がある。<br>ただし画面端が近いとコンボできないので以下のコンボを使用する', 1001),
('luke_impact_punish_counter', 'luke', 'impact', 'punish', 'パニッシュカウンター', '2.HP;tatsu.MP(ジャスト);tatsu.LP(ジャスト);tatsu.HP(ジャスト)', '', '', 'インパクトがパニカンしたら汎用コンボを使用。', 1006),
('luke_impact_stan', 'luke', 'impact', 'stan', 'スタン', 'J.HP;HP;tatsu.MP(ジャスト);tatsu.LP(ジャスト);tatsu.HP(ジャスト)', '', '', '画面端なので汎用コンボは使えません。<br>屈強Pを強Pにし中フラッシュナックルを使わないコンボです。', 1008),
('luke_impact_wall_damage', 'luke', 'impact', 'wall', '壁やられ', 'HP;tatsu.MP(ジャスト);tatsu.LP(ジャスト);tatsu.HP(ジャスト)', '', '', '画面端なので汎用コンボは使えません。<br>屈強Pを強Pにし中フラッシュナックルを使わないコンボです。', 1007),
('luke_jump_cross_up', 'luke', 'jump', 'cross_up', 'めくりヒット', 'J.MK;2.LP;tatsu.LP', '', '', 'めくり(J中K)がヒットしたら4Ｆ始動同様のコンボを使用。', 1004),
('luke_jump_normal', 'luke', 'jump', 'normal', '通常ヒット', 'J.HK;2.HP;tatsu.MP(ジャスト);tatsu.LP(ジャスト);tatsu.HP(ジャスト)', '', '', 'J強Kがヒットしたら汎用コンボを使用。', 1003),
('luke_rush', 'luke', 'rush', '', '', 'Nrush;2.MP;2.HP;tatsu.MP(ジャスト);tatsu.LP(ジャスト);tatsu.HP(ジャスト)', '', '', 'ラッシュ攻撃には、有利フレームを増やす性質があるので屈中Pから屈強Pを打ち汎用コンボを使用。', 1005),
('luke_shimmy', 'luke', 'shimmy', '', '', 'HP;tatsu.MP(ジャスト);tatsu.LP(ジャスト);tatsu.HP(ジャスト)', '', '', '', 1009);
INSERT INTO `combo_point_backup` (`slug`, `char_slug`, `type`, `title`, `img`, `text`, `sort_order`) VALUES
('aki_drive_gauge', 'aki', 'drive_gauge', '', '', '', 1902),
('aki_intrinsic', 'aki', 'intrinsic', '毒破裂', '', '毒破裂はakiの毒をつける技を毒がついた状態の相手に当てると破裂して相手が吹っ飛びコンボがさらにつながるようなことです。', 1901),
('aki_sa_gauge', 'aki', 'sa_gauge', '', '', '', 1903),
('blanka_drive_gauge', 'blanka', 'drive_gauge', '', '', '', 1202),
('blanka_intrinsic', 'blanka', 'intrinsic', 'ブランカちゃん爆弾', '', 'ブランカちゃん爆弾とは、ブランカの固有能力です。<img src=\\\"../img/unique/blanka.png\\\" alt=\\\"ブランカちゃん爆弾画像\\\"><br>ブランカがぬいぐるみ型の爆弾を設置する技で、相手の行動をけん制したり、攻めをサポートするのに使われます。<br>電気のまとう技が爆弾にあたると発動し相手を吹っ飛ばします。また時間がたつと画面から退場します。', 1201),
('blanka_sa_gauge', 'blanka', 'sa_gauge', '', '', '', 1203),
('chunli_drive_gauge', 'chunli', 'drive_gauge', '', '', '', 1502),
('chunli_intrinsic', 'chunli', 'intrinsic', '行雲流水', '', '行雲流水とは、春麗の特殊技で蘭華・這蛇突・蓮掌・前突・仙風・天空脚という6つの技に派生することができコンボや立ち回りの技として使用される。', 1501),
('chunli_sa_gauge', 'chunli', 'sa_gauge', '', '', '', 1503),
('deejay_drive_gauge', 'deejay', 'drive_gauge', '', '', '', 902),
('deejay_intrinsic', 'deejay', 'intrinsic', 'SA2(サンライズフェスティバル)', '', 'サンライズフェスティバルとは、リズムに合わせてボタンを押すことで派生技が発動するリズムゲーム風のスーパーアーツで、成功すれば追加攻撃やコンボにつなげることができます。また派生にはいくつか種類があり状況によって変えたりします。', 901),
('deejay_sa_gauge', 'deejay', 'sa_gauge', '', '', '', 903),
('dhalsim_drive_gauge', 'dhalsim', 'drive_gauge', '', '', '', 1702),
('dhalsim_intrinsic', 'dhalsim', 'intrinsic', 'ヨガフロート・ヨガテレポート', '', 'ヨガフロート=ジャンプ中に空中で一時的に浮遊状態になり、空中攻撃を遅らせたり、タイミングをずらして攻撃を仕掛けられる。<br>ヨガテレポート=一瞬でワープ移動する技。地上・空中どちらからでも発動でき、相手の裏や前方・後方へ素早く移動する。', 1701),
('dhalsim_sa_gauge', 'dhalsim', 'sa_gauge', '', '', '', 1703),
('ed_drive_gauge', 'ed', 'drive_gauge', '', '', '', 2002),
('ed_intrinsic', 'ed', 'intrinsic', 'キルステップ', '', 'エドのキルステップは、高速移動からの攻撃へ派生できる特殊なステップ技です。<br>コマンド：KK（同時押し）<br>派生：6+P早めでキルスイッチ・ブレイク/6+P遅めでキルスイッチ・ロー', 2001),
('ed_sa_gauge', 'ed', 'sa_gauge', '', '', '', 2003),
('ehonda_drive_gauge', 'ehonda', 'drive_gauge', '', '', '', 1102),
('ehonda_intrinsic', 'ehonda', 'intrinsic', '肩屋入り', '', '肩屋入りとは、エドモンド本田の固有の能力です。<img src=\\\"../img/unique/ehonda.png\\\" alt=\\\"肩屋入り画像\\\"><br>コマンドは22+Kで効果は次に出す百貫張り手を強化するという物です。', 1101),
('ehonda_sa_gauge', 'ehonda', 'sa_gauge', '', '', '', 1103),
('elena_drive_gauge', 'elena', 'drive_gauge', '', '', '', 2502),
('elena_intrinsic', 'elena', 'intrinsic', 'ヒーリング', '', '    \"text\":\"\"', 2501),
('elena_sa_gauge', 'elena', 'sa_gauge', '', '', '', 2503),
('gouki_drive_gauge', 'gouki', 'drive_gauge', '', '', '', 2102),
('gouki_intrinsic', 'gouki', 'intrinsic', '阿修羅閃空', '', '阿修羅閃空とは、豪鬼が使う移動する特殊技で、奇襲をかけたり重ねて択をかけたりします。<br>また阿修羅閃空からは朧というコマンド投げに派生する事ができます。', 2101),
('gouki_sa_gauge', 'gouki', 'sa_gauge', '', '', '', 2103),
('guile_drive_gauge', 'guile', 'drive_gauge', '', '', '', 1302),
('guile_intrinsic', 'guile', 'intrinsic', 'ジャストサマー', '', 'ジャストサマーとは、ガイルのサマーソルトキック（2溜め8＋K）をジャスト入力で出した際に強化されるバージョンです。<br>演出が変わりダメージが高くなります。', 1301),
('guile_sa_gauge', 'guile', 'sa_gauge', '', '', '', 1303),
('jamie_drive_gauge', 'jamie', 'drive_gauge', '', '', '', 202),
('jamie_intrinsic', 'jamie', 'intrinsic', '薬湯(酔いレベル)', '', '薬湯(酔いレベル)とは、ジェイミーの固有の能力です。<br><img src=\\\"../img/unique/jamie.png\\\" alt=\\\"酔いレベル画像\\\"><br>レベルはスタート時には0で始まり最大4レベルまで上げることができます。<br>魔身(↓↓＋P)や特定の技の派生から薬湯を飲むとレベルが上がります。<br>レベルを上げると使える技が増えダメージが上がり動きや派生が変わったりします。', 201),
('jamie_sa_gauge', 'jamie', 'sa_gauge', '', '', '', 203),
('jp_drive_gauge', 'jp', 'drive_gauge', '', '', '', 702),
('jp_intrinsic', 'jp', 'intrinsic', 'アムネジア', '', '通常版だと飛び道具と投げ以外の技OD版だと飛び道具以外の全ての技を当身しますまた相手の技の強度によって相手の後隙が変わります。当身についてはこちら<a href=\\\"./Term.html\\\">用語</a>', 701),
('jp_sa_gauge', 'jp', 'sa_gauge', '', '', '', 703),
('juri_drive_gauge', 'juri', 'drive_gauge', '', '', '', 802),
('juri_intrinsic', 'juri', 'intrinsic', '風波ストック', '', '風波ストックとは、ジュリの固有の能力です。<img src=\\\"../img/unique/juri.png\\\" alt=\\\"風波ストック画像\\\"><br>風波ストックはスタート時には0で始まり最大3まで溜めることができます。<br>風波刃という技でストックを溜めることができます。', 801),
('juri_sa_gauge', 'juri', 'sa_gauge', '', '', '', 803),
('ken_drive_gauge', 'ken', 'drive_gauge', '', '', '', 1402),
('ken_intrinsic', 'ken', 'intrinsic', '奮迅脚', '', '奮迅脚はケンの移動技の特殊技でありコンボや奇襲に活用できる強力な技です。<br>また奮迅脚からは、急停止・紫電カカト落とし・踏み込み前蹴りの3つに派生できる。', 1401),
('ken_sa_gauge', 'ken', 'sa_gauge', '', '', '', 1403),
('kimberly_drive_gauge', 'kimberly', 'drive_gauge', '', '', '', 402),
('kimberly_intrinsic', 'kimberly', 'intrinsic', '細工手裏剣', '', '細工手裏剣(細工手裏剣ストック)とは、キンバリーの固有の能力です。<img src=\\\"../img/unique/kimberly.png\\\" alt=\\\"手裏剣ストック画像\\\"><br>細工手裏剣ストックはスタート時には2で始まり↓↓＋Pで手裏剣を設置することができる。<br>↓↓＋PPで二つ一気に設置させること、手裏剣のストックがなくなってから↓↓＋Pでストックを増やすこともできる。', 401),
('kimberly_sa_gauge', 'kimberly', 'sa_gauge', '', '', '', 403),
('lily_drive_gauge', 'lily', 'drive_gauge', '', '', '', 602),
('lily_intrinsic', 'lily', 'intrinsic', '風纏い', '', '風纏いとは、リリーの固有の能力です。<img src=\\\"../img/unique/lily.png\\\" alt=\\\"風纏い画像\\\"><br>風纏いはスタート時には0で始まり最大3までコンドルウィンドという技で溜めることができます。<br>また風纏い中には必殺技の性質が強化されます。', 601),
('lily_sa_gauge', 'lily', 'sa_gauge', '', '', '', 603),
('luke_drive_gauge', 'luke', 'drive_gauge', '', '', '', 102),
('luke_intrinsic', 'luke', 'intrinsic', 'ジャスト', '', 'ジャストとは、ルークの技フラッシュナックルでのボタンホールドで溜め開始から17~20F目にボタンを離すと性能が大きく向上するという性能のことを指す。<br>ジャストが可能なタイミングにはルークの手が光って見え成功するとルークが「ジャスト」と言う。<br>ジャスト入力に成功するとダメージが上がりコンボもつながるようになる。', 101),
('luke_sa_gauge', 'luke', 'sa_gauge', '', '', '', 103),
('mai_drive_gauge', 'mai', 'drive_gauge', '', '', '', 2402),
('mai_intrinsic', 'mai', 'intrinsic', '焔ストック', '', '焔ストックとは、舞の必殺技を強化・派生させるための特殊リソースシステムです。<br>SA1(陽炎の舞)を打つとストックが5個溜まり必殺技を振ると自動で一つ使い技が強化されます。', 2401),
('mai_sa_gauge', 'mai', 'sa_gauge', '', '', '', 2403),
('manon_drive_gauge', 'manon', 'drive_gauge', '', '', '', 302),
('manon_intrinsic', 'manon', 'intrinsic', 'メダル', '', 'メダル(メダルレベル)とは、マノンの固有の能力です。<img src=\\\"../img/unique/manon.png\\\" alt=\\\"メダルレベル画像\\\"><br>レベルははスタート時には1で始まり最大5まで溜めることができます。<br>マネージュ・ドレとランヴェルセのコマンド投げを決めるとメダルが溜まります。<br>コマンド投げ・SA3の威力が上がります。<br>コマンド投げについてはこちらの<a href=\\\"./Term.html\\\">用語</a>をご覧ください。<br>', 301),
('manon_sa_gauge', 'manon', 'sa_gauge', '', '', '', 303),
('marisa_drive_gauge', 'marisa', 'drive_gauge', '', '', '', 502),
('marisa_intrinsic', 'marisa', 'intrinsic', 'アーマー', '', 'マリーザのグラディウス、ファランクス、スクトゥム、SA1(マリーザジャベリン)にはそれぞれアーマー効果がついています。アーマーについてはこちらを<a href=\\\"./Term.html\\\">用語</a><br>', 501),
('marisa_sa_gauge', 'marisa', 'sa_gauge', '', '', '', 503),
('rashid_drive_gauge', 'rashid', 'drive_gauge', '', '', '', 1802),
('rashid_intrinsic', 'rashid', 'intrinsic', 'ラン', '', 'ランとは、ラシードの特殊技で地上を素早く移動しながら、様々な派生技につなげられるダッシュ系の技です。コマンド：前→前（66） または 技後に専用入力<br>派生：バックアップ、テンペスト・ムーン', 1801),
('rashid_sa_gauge', 'rashid', 'sa_gauge', '', '', '', 1803),
('ryu_drive_gauge', 'ryu', 'drive_gauge', '', '', '', 1002),
('ryu_intrinsic', 'ryu', 'intrinsic', '電刃錬気', '', '電刃錬気とは、リュウの固有の能力です。<img src=\\\"../img/unique/ryu.png\\\" alt=\\\"電刃錬気画像\\\"><br>一時的に技の性能を強化する特殊な構えで、攻撃力や連携力を高められる強化手段です。波動拳、波掌撃、SA2などの性能が強化されます。', 1001),
('ryu_sa_gauge', 'ryu', 'sa_gauge', '', '', '', 1003),
('sagat_drive_gauge', 'sagat', 'drive_gauge', '', '', '', 2602),
('sagat_intrinsic', 'sagat', 'intrinsic', '', '', '    \"text\":\"\"', 2601),
('sagat_sa_gauge', 'sagat', 'sa_gauge', '', '', '', 2603),
('terry_drive_gauge', 'terry', 'drive_gauge', '', '', '', 2302),
('terry_intrinsic', 'terry', 'intrinsic', '', '', '    \"text\":\"\"', 2301),
('terry_sa_gauge', 'terry', 'sa_gauge', '', '', '', 2303),
('vega_drive_gauge', 'vega', 'drive_gauge', '', '', '', 2202),
('vega_intrinsic', 'vega', 'intrinsic', 'サイコマイン', '', 'サイコマインとは、ベガが相手自身に付着させるの特殊ギミックで、時間経過かもう一度マインを付ける技を当てると起爆する。', 2201),
('vega_sa_gauge', 'vega', 'sa_gauge', '', '', '', 2203),
('zangief_drive_gauge', 'zangief', 'drive_gauge', '', '', '', 1602),
('zangief_intrinsic', 'zangief', 'intrinsic', 'SA2(サイクロンラリアット)', '', '    \"text\":\"\"', 1601),
('zangief_sa_gauge', 'zangief', 'sa_gauge', '', '', '', 1603);
