(1, 2, 'neutral', 1, NULL, '基本の立ち回り', 'サンドブラストを撃たせつつ、飛びを通すか歩きガードで近づくのが基本になります。', NULL, 1, '2026-04-12 16:39:15', '2026-04-12 16:39:15'),
(2, 2, 'pressure', 1, NULL, 'ラッシュへの対応', '生ラッシュには小技を置いて止めるか、見てから無敵技をパなすのが有効です。', NULL, 2, '2026-04-12 16:39:15', '2026-04-12 16:39:15'),
(3, 2, 'punish', 1, NULL, '大技への反撃', 'フラッシュナックル・強はガードして-4F。小パン等で反撃可能です。', 'flash_knuckle_h', 3, '2026-04-12 16:39:15', '2026-04-12 16:39:15');
INSERT INTO `movelist` (`id`, `character_id`, `move_slug`, `move_type`, `name_jp`, `name_en`, `command`, `parent_slug`, `drive_gauge`, `sa_level`, `condition`, `overview`, `sort_order`, `created_at`, `updated_at`) VALUES
(2, 1, 'hadoken', 'special_moves', '波動拳', 'Hadoken', '236P', NULL, '2', '0', '(電刃錬気中に性質変化)', '前方に気弾を飛ばす技。離れた間合いから攻撃する手段として有効。', 100, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(3, 1, 'shoryuken', 'special_moves', '昇龍拳', 'Shoryuken', '623P', NULL, '2', '0', NULL, '強烈なアッパーと共に飛び上がる技。昇龍拳は相手のジャンプ攻撃に対して無敵となる。', 200, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(4, 1, 'tatsumaki_senpu_kyaku', 'special_moves', '竜巻旋風脚', 'Tatsumaki Senpu-kyaku', '214K', NULL, '2', '0', NULL, '前進する連続回し蹴りを繰り出す技。相手を吹き飛ばすことに長けた回転蹴り。', 300, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(5, 1, 'aerial_tatsumaki_senpu_kyaku', 'special_moves', '空中竜巻旋風脚', 'Aerial Tatsumaki Senpu-kyaku', '214K', NULL, '2', '0', '(前ジャンプ中に)', 'ジャンプ中に繰り出す竜巻旋風脚。ジャンプの軌道を変えたり空中からの奇襲に長けた技。', 400, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(6, 1, 'high_blade_kick', 'special_moves', '上段足刀蹴り', 'High Blade Kick', '236P', NULL, '2', '0', NULL, '素早く間合いを詰める突進蹴り。相手の攻撃の隙を突いたり奇襲を狙える蹴り技で、蹴り足の先端を相手に当てるように繰り出すと有効。', 500, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(7, 1, 'hashogeki', 'special_moves', '波掌撃', 'Hashogeki', '214P', NULL, '2', '0', '(電刃錬気中に性質変化)', '掌に集中させた気を凝縮し前方に放つ技。ガード時の連係やコンボ後の攻め継続として有効。', 600, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(8, 1, 'denjin_charge', 'special_moves', '電刃錬気', 'Denjin Charge', '22P', NULL, '0', '0', NULL, '拳に無の波動を纏い「波動拳」「波掌撃」などの技を強化する技。隙が大きいので使用するタイミングを見極める必要がある。', 700, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(9, 1, 'shinku_hadoken', 'super_arts', '真空波動拳', 'Shinku Hadoken', '236236P', NULL, '0', '1', '(電刃錬気中に性質変化)', '掌に体内の気を集中させ、圧縮して放つ波動拳。攻撃の出が早く、無敵もあるので切り返しとしても使える。', 800, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(10, 1, 'shin_hashogeki', 'super_arts', '真・波掌撃', 'Shin Hashogeki', '214214P', NULL, '0', '2', '(ボタンホールドで性質変化)(電刃錬気中に性質変化)', '精神集中により強化された波掌撃。ボタンをホールドする事で溜めを行い威力を上げることができる。', 900, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(11, 1, 'shin_shoryuken', 'super_arts', '真・昇龍拳', 'Shin Shoryuken', '236236K', NULL, '0', '3', '(体力25%以下で性能がアップ)', '近距離で繰り出す高威力の昇龍拳。相手の急所を狙い確実に倒す切り札。', 1000, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(12, 1, 'collarbone_breaker', 'unique_attacks', '鎖骨割り', 'Collarbone Breaker', '6MP', NULL, '0', '0', NULL, 'しゃがみでガードできない中段攻撃。', 1100, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(13, 1, 'solar_plexus_strike', 'unique_attacks', '鳩尾砕き', 'Solar Plexus Strike', '6HP', NULL, '0', '0', NULL, '前進して繰り出す、ガードされても相手より先に動ける突き。', 1200, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(14, 1, 'short_uppercut', 'unique_attacks', '上げ突き', 'Short Uppercut', '4HP', NULL, '0', '0', NULL, '技の出が早い必殺技キャンセル可能な突き。', 1300, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(15, 1, 'axe_kick', 'unique_attacks', 'かかと落とし', 'Axe Kick', '4HK', NULL, '0', '0', NULL, '必殺技キャンセル可能な連続でヒットする蹴り。', 1400, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(16, 1, 'whirlwind_kick', 'unique_attacks', '旋風脚', 'Whirlwind Kick', '6HK', NULL, '0', '0', NULL, '相手の足払いに対して強いリーチの長い蹴り。', 1500, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(17, 1, 'high_double_strike', 'unique_attacks', '上段二連撃', 'High Double Strike', 'HP~HK(2Pで電刃錬気にキャンセル可能)', NULL, '0', '0', NULL, '連係を出す入力猶予が長く、続けてヒットする攻撃。', 1600, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(18, 1, 'fuwa_triple_strike', 'unique_attacks', '不破三連撃', 'Fuwa Triple Strike', 'MP~LK~HK(2Pで電刃錬気にキャンセル可能)', NULL, '0', '0', NULL, '連係を途中で止めても隙が少ない連続攻撃。', 1700, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(19, 1, 'shoulder_throw', 'throws', '背負い投げ', 'Shoulder Throw', 'Nor6LPLK', NULL, '0', '0', '(近距離で)', '相手を掴み、腕を支点に背負う形から前方へ投げ落とす技。相手との位置関係を変えずに投げる。', 1800, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(20, 1, 'somersault_throw', 'throws', '巴投げ', 'Somersault Throw', '4LPLK', NULL, '0', '0', '(近距離で)', '相手を掴み、体に足を掛けて後方へ倒れ込むように投げる技。相手との位置を入れ替えながら投げる。', 1900, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(21, 1, 'drive_impact', 'common_moves', 'ドライブインパクト（震撃）', 'Drive Impact: Shingeki', 'HPHK', NULL, '1', '0', NULL, '相手の技を受け止めながら攻撃に移る事ができる。ステージ端で当てると、追撃可能な壁ダメージを誘発する。', 2000, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(22, 1, 'drive_reversal', 'common_moves', 'ドライブリバーサル（胸尖打ち）', 'Drive Reversal: Chest Strike', '6HPHK', NULL, '2', '0', '(ガード中 or ドライブパリィ成立中 or 起き上がり時に)', '攻撃をガードした状態、または起き上がり時に切り返して攻守を逆転する事ができる。起き上がり時のみホールドで発動可能。', 2100, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(23, 1, 'drive_parry', 'common_moves', 'ドライブパリィ', 'Drive Parry', 'MPMK', NULL, 'hold', '0', '(ボタンホールドで動作継続)', 'その場で構えを取り、相手のすべての打撃技を受け止める動作。ボタンを押し続ける事で構えを維持する事ができる。', 2200, '2026-03-16 10:57:17', '2026-03-19 14:28:59'),
(24, 1, 'parry_drive_rush', 'common_moves', 'ドライブラッシュ', 'Parry Drive Rush', '66', 'drive_parry', '0.5', '0', '(ドライブパリィ中に)', 'ドライブパリィの構えから即座に前方へ移動する動作。移動中に出す通常技、特殊技は、性能が変化する。', 2300, '2026-03-16 10:57:17', '2026-03-16 10:57:17'),
(25, 1, 'cancel_drive_rush', 'common_moves', 'キャンセルドライブラッシュ', 'Cancel Drive Rush', '66or(Nor6)MPMK', NULL, '3', '0', '(必殺技キャンセル可能な攻撃ヒット中に)', '攻撃から即座に前方へ移動する動作。必殺技キャンセル可能な技から発動可能。', 2400, '2026-03-16 10:57:18', '2026-03-19 14:28:59'),
(26, 2, 'sand_blast', 'special_moves', 'サンドブラスト', 'Sand Blast', '236P', NULL, '2', '0', NULL, '前方へ拳圧による衝撃波を飛ばす技。離れた間合いのけん制や連係の繋ぎとして有効。', 100, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(27, 2, 'fatal_shot', 'special_moves', 'フェイタルショット', 'Fatal Shot', 'PP', 'sand_blast', '1', '0', '(ODサンドブラスト後に)', 'ODサンドブラストから続けて衝撃波を飛ばす技。飛び道具の撃ち合いからダメージを上乗せするのに有効。', 200, '2026-03-16 10:57:36', '2026-03-16 10:57:36'),
(28, 2, 'flash_knuckle', 'special_moves', 'フラッシュナックル', 'Flash Knuckle', '214P', NULL, '2', '0', '(ボタンホールドで性質変化)', '腕に力を溜めて全力で殴りつける技。出始めからボタンをホールドすると威力が増し、腕が光る瞬間にホールドを解除する事で、さらに性能が強化される。', 300, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(29, 2, 'ddt', 'special_moves', 'DDT', 'DDT', 'PP', 'flash_knuckle', '1', '0', '(ODフラッシュナックル後に)', 'ODフラッシュナックル初段から派生する強力な投げ技。確実にダメージを奪いたい状況で使いやすい。', 400, '2026-03-16 10:57:36', '2026-03-16 10:57:36'),
(30, 2, 'aerial_flash_knuckle', 'special_moves', 'エアフラッシュナックル', 'Aerial Flash Knuckle', '214P', NULL, '2', '0', '(垂直 or 前ジャンプ中に)(ボタンホールドで性質変化)', 'ジャンプ中に繰り出すフラッシュナックル。ジャンプの軌道を変えての奇襲や空中コンボへ組み込むのに有効。', 500, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(31, 2, 'avenger', 'special_moves', 'アベンジャー', 'Avenger', '236K', NULL, '2', '0', NULL, '前傾姿勢で前進する技。動作中にボタン入力でそれぞれの派生技へ移行する。', 600, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(32, 2, 'no_chaser', 'special_moves', 'ノーチェイサー', 'No Chaser', 'P', 'avenger', '0', '0', '(アベンジャー中に)', 'アベンジャーから派生する、強力なタックルを繰り出す技。攻撃が出ている時間が長く、攻め込む手段として有効。', 700, '2026-03-16 10:57:36', '2026-03-16 10:57:36'),
(33, 2, 'impaler', 'special_moves', 'インパラー', 'Impaler', 'K', 'avenger', '0', '0', '(アベンジャー中に)', 'アベンジャーから派生する、しゃがみガードできない浴びせ蹴り。奇襲でのガード崩しやコンボに組み込むのが有効。', 800, '2026-03-16 10:57:36', '2026-03-16 10:57:36'),
(34, 2, 'rising_uppercut', 'special_moves', 'ライジングアッパー', 'Rising Uppercut', '623P', NULL, '2', '0', NULL, '斜め上へ勢いよく跳び上がりながら強烈なアッパーを繰り出す技。相手のジャンプ攻撃に対して無敵があるので、対空として使える。', 900, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(35, 2, 'slam_dunk', 'special_moves', 'スラムダンク', 'Slam Dunk', 'PP', 'rising_uppercut', '1', '0', '(ODライジングアッパー後に)', 'ODライジングアッパーからさらに叩き付け攻撃を行う技。ダメージの大きさとヒット後の状況に優れる。', 1000, '2026-03-16 10:57:36', '2026-03-16 10:57:36'),
(36, 2, 'vulcan_blast', 'super_arts', 'バルカンブラスト', 'Vulcan Blast', '236236P', NULL, '0', '1', NULL, 'サンドブラストを高速で連打する技。攻撃の出が早く、飛び道具の撃ち合いやコンボに使いやすい。', 1100, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(37, 2, 'eraser', 'super_arts', 'イレイザー', 'Eraser', '214214P', NULL, '0', '2', NULL, 'パンチの連続攻撃から強烈なフィニッシュブローで吹き飛ばす技。初段がヒットする事でその後の連続攻撃が発動する。', 1200, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(38, 2, 'pale_rider', 'super_arts', 'ペイルライダー', 'Pale Rider', '236236K', NULL, '0', '3', '(体力25%以下で性能がアップ)', '突進からマウントポジションを取って渾身のパンチを叩き込む技。前進距離が長く、コンボへの組み込みや飛び道具対策に使える。', 1300, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(39, 2, 'rawhide', 'unique_attacks', 'ローハイド', 'Rawhide', '6MP', NULL, '0', '0', NULL, 'しゃがみでガードできない中段攻撃。', 1400, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(40, 2, 'suppressor', 'unique_attacks', 'サプレッサー', 'Suppressor', '4HP', NULL, '0', '0', NULL, '後方へ下がった後に繰り出す必殺技キャンセル可能な突き。', 1500, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(41, 2, 'outlaw_kick', 'unique_attacks', 'アウトローキック', 'Outlaw Kick', '4HK', NULL, '0', '0', NULL, '相手のジャンプに対して強いハイキック。', 1600, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(42, 2, 'double_impact', 'unique_attacks', 'ダブルインパクト', 'Double Impact', '6HP~HP', NULL, '0', '0', NULL, '前進して繰り出す、2段目が必殺技キャンセル可能な連続攻撃。', 1700, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(43, 2, 'triple_impact', 'unique_attacks', 'トリプルインパクト', 'Triple Impact', 'LP~MP~HP', NULL, '0', '0', NULL, '技の出が早い必殺技キャンセル可能な連続攻撃。', 1800, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(44, 2, 'nose_breaker', 'unique_attacks', 'ノーズブレイカー', 'Nose Breaker', '2MK~2HP', NULL, '0', '0', NULL, '続けてヒットする、初段が立ってガードできない連続攻撃。', 1900, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(45, 2, 'snapback_combo', 'unique_attacks', 'スナップバックコンボ', 'Snapback Combo', 'MP~MP~MP~MP', NULL, '0', '0', NULL, '2段目までスーパーアーツでキャンセル可能な連続攻撃。', 2000, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(46, 2, 'sweeper', 'throws', 'スウィーパー', 'Sweeper', 'Nor6LPLK', NULL, '0', '0', '(近距離で)', '相手を掴んで持ち上げ、背中から叩き付ける投げ技。相手との位置関係を変えずに投げる。', 2100, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(47, 2, 'scrapper', 'throws', 'スクラッパー', 'Scrapper', '4LPLK', NULL, '0', '0', '(近距離で)', '相手の頭を掴み、2発の膝蹴りで相手を吹き飛ばす技。相手との位置を入れ替えながら投げる。', 2200, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(48, 2, 'drive_impact', 'common_moves', 'ドライブインパクト（マズルフラッシュ）', 'Drive Impact: Muzzle Flash', 'HPHK', NULL, '1', '0', NULL, '相手の技を受け止めながら攻撃に移る事ができる。ステージ端で当てると、追撃可能な壁ダメージを誘発する。', 2300, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(49, 2, 'drive_reversal', 'common_moves', 'ドライブリバーサル（バッターリングラム）', 'Drive Reversal: Battering Ram', '6HPHK', NULL, '2', '0', '(ガード中 or ドライブパリィ成立中 or 起き上がり時に)', '攻撃をガードした状態、または起き上がり時に切り返して攻守を逆転する事ができる。起き上がり時のみホールドで発動可能。', 2400, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(50, 2, 'drive_parry', 'common_moves', 'ドライブパリィ', 'Drive Parry', 'MPMK', NULL, 'hold', '0', '(ボタンホールドで動作継続)', 'その場で構えを取り、相手のすべての打撃技を受け止める動作。ボタンを押し続ける事で構えを維持する事ができる。', 2500, '2026-03-16 10:57:36', '2026-03-19 14:28:59'),
(51, 2, 'parry_drive_rush', 'common_moves', 'ドライブラッシュ', 'Parry Drive Rush', '66', 'drive_parry', '0.5', '0', '(ドライブパリィ中に)', 'ドライブパリィの構えから即座に前方へ移動する動作。移動中に出す通常技、特殊技は、性能が変化する。', 2600, '2026-03-16 10:57:36', '2026-03-16 10:57:36'),
(52, 2, 'cancel_drive_rush', 'common_moves', 'キャンセルドライブラッシュ', 'Cancel Drive Rush', '66or(Nor6)MPMK', NULL, '3', '0', '(必殺技キャンセル可能な攻撃ヒット中に)', '攻撃から即座に前方へ移動する動作。必殺技キャンセル可能な技から発動可能。', 2700, '2026-03-16 10:57:37', '2026-03-19 14:28:59'),
(53, 3, 'the_devil_inside', 'special_moves', '魔身', 'The Devil Inside', '22P', NULL, '0', '0', '(ボタンホールドで動作継続)', '瓢箪を取り出し、気を開放する薬湯を飲む技。飲むと酔いLvが上昇し、上昇したLvに応じた技が開放される。', 100, '2026-03-16 10:59:47', '2026-03-19 14:28:59'),
(54, 3, 'freeflow_strikes', 'special_moves', '流酔拳', 'Freeflow Strikes', '236P~6P~6P', NULL, '2', '0', '(酔いLv4以上で動作が変化)', '前進して拳での3連撃を繰り出す技。通常技からのコンボ始動技として有効。', 200, '2026-03-16 10:59:47', '2026-03-19 14:28:59'),
(55, 3, 'freeflow_kicks', 'special_moves', '流酔脚', 'Freeflow Kicks', '236P~6K~6K', NULL, '2', '0', NULL, '拳での攻撃から蹴りの連撃を繰り出す技。すべての派生を出し切った後は酔いLvが上昇する。', 300, '2026-03-16 10:59:47', '2026-03-19 14:28:59'),
